import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"OAuth 2.1 Provider Dogfood — integrated release gate report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oauth21-provider.md","filePath":"quality-reports/auth/oauth21-provider.md"}'),r={name:"quality-reports/auth/oauth21-provider.md"};function s(c,e,i,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="oauth-2-1-provider-dogfood-—-integrated-release-gate-report" tabindex="-1">OAuth 2.1 Provider Dogfood — integrated release gate report <a class="header-anchor" href="#oauth-2-1-provider-dogfood-—-integrated-release-gate-report" aria-label="Permalink to &quot;OAuth 2.1 Provider Dogfood — integrated release gate report&quot;">​</a></h1><p>Integrated release gate for <code>examples/dogfood-oauth21-provider</code> v1.21-3 (<code>#844</code>). Sub-Issue <strong>v1.21-3d</strong> (<code>#867</code>) closes out the milestone by landing revocation cascade + real vs mock fidelity harness + this 7-axis integrated release gate.</p><p>Sibling reports (kept for depth-of-detail per Sub-Issue):</p><ul><li><code>oauth21-provider-endpoints.md</code> — v1.21-3a (<code>#864</code>) 4-axis skeleton</li><li><code>oauth21-provider-pkce.md</code> — v1.21-3b (<code>#865</code>) 4-axis PKCE</li><li><code>oauth21-provider-dpop-refresh.md</code> — v1.21-3c (<code>#866</code>) 8-axis DPoP + rotation</li></ul><h2 id="release-gate-—-7-axes" tabindex="-1">Release gate — 7 axes <a class="header-anchor" href="#release-gate-—-7-axes" aria-label="Permalink to &quot;Release gate — 7 axes&quot;">​</a></h2><p>The gate is passed when every axis has an assertion contract with mock coverage that runs unconditionally, plus a real column that either runs live (when <code>OAUTH21_BOOTSTRAP=1</code> + <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> are set) or documents the env-skip contract.</p><table tabindex="0"><thead><tr><th>#</th><th>axis</th><th>RFC anchor</th><th>mock (<code>@kiwa-lab/auth</code>)</th><th>real (oauth2-mock-server, gated by <code>OAUTH21_BOOTSTRAP=1</code>)</th><th>status</th></tr></thead><tbody><tr><td>1</td><td>behavioural fidelity (real vs mock)</td><td>RFC 6749 §5.1 / RFC 7009 §2 / RFC 7662 §2.2 / RFC 8414 §2</td><td><code>tests/fidelity-harness.spec.ts</code> runs 5 endpoints × 4 axes = 20 comparison points against the mock unconditionally; each point pins shape + trace + contract + env-skip</td><td>Real column reports <code>KIWA_OAUTH21_ENV_MISSING</code> on every non-discovery method until the CI runner sets <code>OAUTH21_BOOTSTRAP=1</code> + <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> — the discovery endpoint stays green regardless because the shape is static per issuer</td><td>PASS</td></tr><tr><td>2</td><td>performance harness (mock + live throughput)</td><td>RFC 6749 §6 non-functional envelope</td><td>Mock harness completes 136 spec assertions in <code>&lt; 400 ms</code> (vitest run) — the AS never crosses process boundary, every call is in-process, no <code>await</code> on I/O; this is the ceiling that a live driver has to fit under to be considered &quot;fast enough&quot; for release</td><td>Live harness inherits the same shape once <code>oauth2-mock-server</code> is wired; the container adds a docker startup cost (&lt; 5 s per suite) plus HTTP round-trip (&lt; 5 ms per call) that stays outside the release gate budget of 30 s per spec file</td><td>PASS</td></tr><tr><td>3</td><td>discovery metadata completeness</td><td>RFC 8414 §2 + RFC 9700 §2.1</td><td><code>endpoints-skeleton.spec.ts</code> axis 1 pins the full <code>DiscoveryMetadata</code> shape: <code>issuer</code>, <code>authorization_endpoint</code>, <code>token_endpoint</code>, <code>revocation_endpoint</code>, <code>introspection_endpoint</code>, <code>jwks_uri</code>, <code>response_types_supported=[code]</code>, <code>grant_types_supported=[authorization_code, refresh_token]</code>, <code>code_challenge_methods_supported=[S256]</code>, <code>dpop_signing_alg_values_supported=[ES256]</code>; <code>fidelity-harness.spec.ts</code> endpoint 1 asserts mock = real for the shape</td><td>Real column emits the same document (static shape derived from issuer) even without a container — <code>makeRealAdapter.discovery()</code> is the one method that always returns the shape so a client can inspect the metadata before deciding whether to attempt the real flow</td><td>PASS</td></tr><tr><td>4</td><td>OAuth 2.1 hardening (implicit / plain / password refuse)</td><td>RFC 9700 §2.1 + RFC 9700 §2</td><td><code>endpoints-skeleton.spec.ts</code> axis 2 + 3 covers <code>response_type=token</code> → <code>unsupported_response_type</code>, <code>code_challenge_method=plain</code> → <code>invalid_request</code>, `grant_type=password</td><td>client_credentials<code>→</code>unsupported_grant_type<code>; </code>pkce-flow.spec.ts<code>deepens PKCE + hardened refusals;</code>fidelity-harness.spec.ts<code>endpoints 2 + 3 pin the same refusals through the</code>/authorize<code>+</code>/token` fidelity contract</td><td>Real driver refuses same downgrades at the HTTP layer with the same error codes; the release gate contract is that a client trying to downgrade cannot pass discovery + fail at runtime in a different way on the two drivers</td></tr><tr><td>5</td><td>DPoP proof binding</td><td>RFC 9449 §4.2 + §4.3</td><td><code>dpop-flow.spec.ts</code> covers 4 axes × 27 tests: header alg (<code>ES256</code> + <code>dpop+jwt</code> only), <code>htm</code> + <code>htu</code> binding, <code>iat</code> skew tolerance (default 60 s), <code>jti</code> replay guard; every rejection surfaces as <code>invalid_dpop_proof</code> with a <code>kind</code> field for client debugging</td><td>Real driver enforces same binding server-side with the same rejection code; env-skip contract asserted through <code>dpop-flow.spec.ts</code> describe block <code>real adapter — DPoP env-skip contract</code></td><td>PASS</td></tr><tr><td>6</td><td>refresh rotation + reuse detection</td><td>RFC 9700 §2.2 + §2.2.2 + RFC 6749 §5.1</td><td><code>refresh-rotation.spec.ts</code> covers 4 axes × 20 tests: rotation on use (<code>rotationCount</code> increments, 5-step chain produces 6 distinct tokens), reuse detection (<code>kind=refresh_token_reused</code>), expiry enforcement (<code>kind=refresh_token_expired</code>), binding preservation (DPoP <code>jkt</code> inherited across rotation)</td><td>Real driver rotates + tears down family with the same kind separation; env-skip contract asserted through the spec&#39;s <code>real adapter — refresh-rotation env-skip contract</code> describe block</td><td>PASS</td></tr><tr><td>7</td><td>revocation cascade</td><td>RFC 7009 §2 + §2.2 + RFC 9700 §2.2.2</td><td><code>revocation-cascade.spec.ts</code> covers 4 axes × 22 tests: access_token revoke → <code>/introspect</code> flip to <code>active=false</code>; cascade to refresh (revoking access invalidates sibling refresh); reuse-after-revoke refused; idempotency (double revoke is 200 both times, cascade fan-out reports zero on second call); scope guarantees (cascade does not touch other subjects on same client, does not touch same subject on different client)</td><td>Real column reports <code>KIWA_OAUTH21_ENV_MISSING</code> on revoke + introspect until <code>oauth2-mock-server</code> is wired; the <code>real adapter — revocation cascade env-skip contract</code> describe block pins the trace shape</td><td>PASS</td></tr></tbody></table><h2 id="fidelity-axes-revocation-cascade" tabindex="-1">Fidelity axes (revocation-cascade) <a class="header-anchor" href="#fidelity-axes-revocation-cascade" aria-label="Permalink to &quot;Fidelity axes (revocation-cascade)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>RFC anchor</th><th>mock (<code>@kiwa-lab/auth</code>)</th><th>real (oauth2-mock-server, gated by <code>OAUTH21_BOOTSTRAP=1</code>)</th><th>assertion</th></tr></thead><tbody><tr><td>1. access_token revoke</td><td>RFC 7009 §2</td><td><code>/revoke</code> on an access_token deletes it from the AS active registry; <code>/introspect</code> returns <code>{active: false}</code> on the next lookup; body is empty (200) per RFC 7009 §2.2</td><td>oauth2-mock-server same delete + introspect flip</td><td>Revocation is the primary defence when a resource server discovers a leaked token; the AS must publish the state transition through <code>/introspect</code> immediately.</td></tr><tr><td>2. cascade to refresh</td><td>RFC 9700 §2.2.2</td><td>Revoking an access_token invalidates the sibling refresh_token minted from the same grant; subsequent <code>grant_type=refresh_token</code> on the sibling fails with <code>invalid_grant</code>; cascade fans out across multiple grants sharing the same <code>(clientId, subject)</code> pair</td><td>oauth2-mock-server tears down family with the same fan-out semantics</td><td>RFC 9700 §2.2.2 requires that any signal of compromise tear down the whole family — cascade prevents an attacker with a leaked access_token from silently rotating into a fresh refresh_token.</td></tr><tr><td>3. reuse after revoke</td><td>RFC 7009 §2.2</td><td>A revoked refresh_token cannot mint fresh pairs (<code>invalid_grant</code>); a revoked access_token flips <code>/introspect</code> to <code>active=false</code> permanently; cross-client revoke is refused silently (RFC 7009 §2.1 client credential mismatch — legitimate token stays active)</td><td>oauth2-mock-server same refusal semantics</td><td>Revocation state must be authoritative — a client that revokes then refreshes must fail, and an attacker who tries to revoke under a different client_id must not affect the legitimate token.</td></tr><tr><td>4. idempotency</td><td>RFC 7009 §2.2</td><td>Revoking the same token twice returns 200 both times; <code>cascadeRevoke</code> on an already-revoked family reports zero fan-out (<code>accessTokensRevoked=0</code>, <code>refreshTokensRevoked=0</code>, <code>family=null</code>); <code>createCascadeRevokeHandler</code> swallows unknown tokens with an empty report</td><td>oauth2-mock-server same idempotent semantics</td><td>RFC 7009 §2.2 requires idempotent revocation — a client that retries a revoke request must not observe a 400 the second time.</td></tr></tbody></table><h2 id="cascade-implementation-notes" tabindex="-1">Cascade implementation notes <a class="header-anchor" href="#cascade-implementation-notes" aria-label="Permalink to &quot;Cascade implementation notes&quot;">​</a></h2><ul><li><code>src/lib/revocation-cascade.ts</code> exposes <code>cascadeRevoke(as, token, clientId)</code> and <code>locateGrantFamily(as, token)</code>. The wrapper reconstructs the grant family by filtering <code>listAccessTokens()</code> + <code>listRefreshTokens()</code> on the <code>(clientId, subject)</code> pair of the target token because the kiwa AS does not persist an explicit grant family id.</li><li>Cascade scope is <code>(clientId, subject)</code> rather than <code>(clientId, subject, scope)</code> on purpose — RFC 9700 §2.2.2 mandates full family teardown when compromise is suspected, and a legitimate client can always re-obtain a narrower grant afterwards. Narrowing the scope filter would leave a scoped subset alive.</li><li>The wrapper delegates the actual token-level revocation to the kiwa AS&#39;s <code>revoke(token, clientId)</code> primitive so the AS state machine stays in charge of the write. This preserves RFC 7009 §2.2 idempotency and ensures <code>/introspect</code> picks up the revoked state through the AS&#39;s existing lookup.</li><li><code>CascadeRevocationReport</code> publishes <code>accessTokensRevoked</code> + <code>refreshTokensRevoked</code> + <code>family</code> so tests can assert fan-out size without having to grep the token registry manually. Cross-client attempts return an empty report (family stays <code>null</code> when the AS rejects the mismatched client credential).</li><li>The Hono <code>/revoke</code> handler in <code>src/lib/hono-app.ts</code> invokes cascade only when <code>CreateHonoAppOptions.cascadeAs</code> is supplied — legacy callers that pass only the adapter surface still get RFC 7009 single-token revocation, so the cascade is opt-in and backward-compatible with the pre-#867 API.</li></ul><h2 id="real-adapter-scaffolding" tabindex="-1">Real-adapter scaffolding <a class="header-anchor" href="#real-adapter-scaffolding" aria-label="Permalink to &quot;Real-adapter scaffolding&quot;">​</a></h2><p>The env-skip contract established in Sub-Issue <code>#865</code> carries forward unchanged — <code>startOAuth2MockServer()</code> in <code>src/adapters/real.ts</code> still routes through <code>OAUTH21_BOOTSTRAP=1</code> + optional <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> for the pre-v1.22-2 docker-compose flow. Sub-Issue v1.22-2 (<code>#888</code>) layered a testcontainers boot path (<code>startOAuth2MockServerContainer()</code>) that boots <code>ghcr.io/navikt/mock-oauth2-server</code> in-process so the release-gate leg gets live coverage without needing an external docker-compose harness.</p><p><code>makeRealAdapter</code> continues to record every failed method call with <code>errorKind=&#39;KIWA_OAUTH21_ENV_MISSING&#39;</code> so the fidelity harness captures &quot;environment absent&quot; rather than &quot;assertion failed&quot;; every axis in the fidelity grid adds an env-skip smoke test that pins this behaviour.</p><h2 id="real-driver-coverage-v1-22-2" tabindex="-1">Real driver coverage (v1.22-2) <a class="header-anchor" href="#real-driver-coverage-v1-22-2" aria-label="Permalink to &quot;Real driver coverage (v1.22-2)&quot;">​</a></h2><p>Sub-Issue v1.22-2 (<code>#888</code>) wires the testcontainers path so the <code>discovery</code> axis gets live coverage against a real oauth2-mock-server. The other axes stay on the mock-as-reference matrix documented in § Real coverage matrix below — the sync <code>OAuth21ASAdapter</code> interface cannot express the HTTP round-trip required by <code>/authorize</code> / <code>/token</code> / <code>/revoke</code> / <code>/introspect</code> through a live driver; those axes need a Sub-Issue v1.22-N follow-up that extends the interface with async counterparts.</p><p>The v1.22-2 real driver also exposed <strong>Bug 1</strong> in the pre-v1.22-2 <code>/authorize</code> handler — the AS returned JSON on post-adapter refusals instead of the RFC 6749 §4.1.2.1-mandated 302 redirect. Because real IdPs (Navikt oauth2-mock-server, Keycloak, Auth0) all redirect, the mock&#39;s JSON response would have failed the fidelity harness under the real driver. The fix redirects to <code>redirect_uri?error=&lt;code&gt;&amp;error_description=&lt;msg&gt;&amp;state=&lt;state&gt;</code> for every refusal whose <code>redirect_uri</code> + <code>client_id</code> are validly formed; untrusted URI cases (missing / malformed / unregistered redirect_uri) stay on JSON per §4.1.2.1&#39;s &quot;cannot trust the URI&quot; caveat.</p><h3 id="real-coverage-matrix" tabindex="-1">Real coverage matrix <a class="header-anchor" href="#real-coverage-matrix" aria-label="Permalink to &quot;Real coverage matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>axis</th><th>mock (release gate reference)</th><th>real (testcontainers <code>ghcr.io/navikt/mock-oauth2-server</code>)</th><th>v1.22-2 status</th></tr></thead><tbody><tr><td>discovery metadata shape</td><td><code>endpoints-skeleton.spec.ts</code> axis 1 pins the RFC 8414 §2 shape (<code>issuer</code>, <code>authorization_endpoint</code>, <code>token_endpoint</code>, <code>revocation_endpoint</code>, <code>introspection_endpoint</code>, <code>jwks_uri</code>, <code>response_types_supported=[code]</code>, <code>grant_types_supported=[authorization_code, refresh_token]</code>, <code>code_challenge_methods_supported=[S256]</code>, <code>dpop_signing_alg_values_supported=[ES256]</code>)</td><td><code>oauth2-mock-real-driver.spec.ts</code> (opt-in <code>OAUTH21_BOOTSTRAP=1</code>) — real driver fetches Keycloak-shaped discovery from Navikt mock, kiwa contract narrows on the OAuth 2.1 hardened subset. Both drivers advertise <code>response_types_supported=[code]</code> + <code>code_challenge_methods_supported=[S256]</code> — the invariants OAuth 2.1 refuses to compromise on</td><td><strong>LIVE</strong> — axis 1</td></tr><tr><td>/authorize error redirect (RFC 6749 §4.1.2.1)</td><td><code>authorize-error-redirect.spec.ts</code> — 302 redirect fidelity for missing code_challenge / missing state / bad response_type; JSON fallback for untrusted URI</td><td>Navikt oauth2-mock-server redirects per §4.1.2.1 — kiwa mock now matches after v1.22-2 Bug 1 fix. Sync interface cannot fetch live so the release-gate reference stays on the mock&#39;s 302 assertion</td><td>mock-as-reference (contract diff verified statically)</td></tr><tr><td>/authorize ceremony</td><td><code>fidelity-harness.spec.ts</code> endpoint 2 (shape / trace / contract / env-skip) — mock returns 302 + code + state</td><td>Interface parity refuse — sync <code>authorize()</code> on real driver throws <code>KIWA_OAUTH21_ENV_MISSING</code> even in env-ready mode with a distinguishable &quot;sync interface + async HTTP ceremony&quot; detail</td><td>mock-as-reference (async surface follow-up)</td></tr><tr><td>/token ceremony</td><td><code>fidelity-harness.spec.ts</code> endpoint 3 + <code>pkce-flow.spec.ts</code> + <code>dpop-flow.spec.ts</code> + <code>refresh-rotation.spec.ts</code></td><td>Interface parity refuse — same as <code>/authorize</code></td><td>mock-as-reference (async surface follow-up)</td></tr><tr><td>/revoke ceremony</td><td><code>fidelity-harness.spec.ts</code> endpoint 4 + <code>revocation-cascade.spec.ts</code></td><td>Interface parity refuse</td><td>mock-as-reference</td></tr><tr><td>/introspect ceremony</td><td><code>fidelity-harness.spec.ts</code> endpoint 5 + <code>revocation-cascade.spec.ts</code></td><td>Interface parity refuse</td><td>mock-as-reference</td></tr></tbody></table><h3 id="real-vs-mock-fidelity-—-measurement-plan" tabindex="-1">Real vs mock fidelity — measurement plan <a class="header-anchor" href="#real-vs-mock-fidelity-—-measurement-plan" aria-label="Permalink to &quot;Real vs mock fidelity — measurement plan&quot;">​</a></h3><ul><li>Discovery axis runs live under <code>OAUTH21_BOOTSTRAP=1</code> — the kiwa <code>DiscoveryMetadata</code> contract is narrowed onto Navikt&#39;s superset in <code>fetchDiscoveryFromMock()</code>, so the diff is on the fields the release gate cares about (RFC 8414 mandatory + OAuth 2.1 hardened subset). Endpoint URL differences (Navikt hosts at <code>/{issuer}/authorization</code> vs kiwa mock&#39;s <code>/authorize</code>) are legitimate driver-specific and DO NOT count as a divergence — the assertion narrows to <code>response_types_supported</code> + <code>code_challenge_methods_supported</code> + <code>grant_types_supported</code> which OAuth 2.1 refuses to compromise on.</li><li>Ceremonial endpoints stay on the mock-as-reference matrix because the sync interface cannot host the HTTP round-trip. The v1.22-2 fixture verifies interface parity — every ceremonial method refuses in env-ready mode with a &quot;sync interface + async HTTP ceremony&quot; detail, so no silent divergence is possible.</li><li>Bug 1 fix (§4.1.2.1 redirect) was surfaced by asking &quot;what does Navikt&#39;s mock do?&quot; during the v1.22-2 wiring. The static contract check in <code>authorize-error-redirect.spec.ts</code> pins the 302 shape without needing a live container — the release gate stays deterministic even without docker-in-CI.</li></ul><h2 id="test-coverage-summary-integrated" tabindex="-1">Test coverage summary (integrated) <a class="header-anchor" href="#test-coverage-summary-integrated" aria-label="Permalink to &quot;Test coverage summary (integrated)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>spec file</th><th>describe blocks</th><th>tests</th><th>axes covered</th></tr></thead><tbody><tr><td><code>tests/endpoints-skeleton.spec.ts</code></td><td>4 axes + real env-skip</td><td>15</td><td>discovery / authorize / token / revoke+introspect skeleton</td></tr><tr><td><code>tests/pkce-flow.spec.ts</code></td><td>4 axes + real env-skip</td><td>31</td><td>verifier entropy / challenge derivation / S256 method / verifier mismatch</td></tr><tr><td><code>tests/dpop-flow.spec.ts</code></td><td>4 axes + real env-skip</td><td>27</td><td>header alg / htm+htu binding / iat skew / jti replay</td></tr><tr><td><code>tests/refresh-rotation.spec.ts</code></td><td>4 axes + real env-skip</td><td>20</td><td>rotation on use / reuse detection / expiry / binding preservation</td></tr><tr><td><code>tests/revocation-cascade.spec.ts</code></td><td>4 axes + real env-skip</td><td>22</td><td>access revoke / cascade to refresh / reuse-after-revoke / idempotency</td></tr><tr><td><code>tests/fidelity-harness.spec.ts</code></td><td>5 endpoints × 4 axes + grid summary</td><td>21</td><td>shape / trace / contract / env-skip across every RFC 9700 endpoint</td></tr><tr><td><code>tests/authorize-error-redirect.spec.ts</code> (v1.22-2)</td><td>4 tests</td><td>4</td><td>RFC 6749 §4.1.2.1 redirect fidelity (missing code_challenge / missing state / bad response_type / untrusted URI JSON fallback)</td></tr><tr><td><code>tests/oauth2-mock-real-driver.spec.ts</code> (v1.22-2)</td><td>env-detect + env-missing + env-ready parity + network-error + opt-in live coverage</td><td>15 always-on + 3 opt-in</td><td>env-skip semantics + sync interface parity + discovery axis live diff</td></tr></tbody></table><p><strong>Total: 155 always-on tests + 3 opt-in live tests across the 8 spec files. <code>pnpm test</code> (mock-only) reports 155 pass / 3 skipped. <code>OAUTH21_BOOTSTRAP=1 pnpm test</code> (live) reports 158 pass with the Navikt container booted (~10s on warm cache).</strong></p><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every axis runs unconditionally.</li><li><code>OAUTH21_BOOTSTRAP=1</code> — opt-in for real ceremonies. Two paths: <ul><li><code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> — the harness targets an externally-managed oauth2-mock-server (docker-compose flow, pre-v1.22-2)</li><li>No URL set — v1.22-2 <code>oauth2-mock-real-driver.spec.ts</code> boots the container itself through <code>startOAuth2MockServerContainer()</code></li></ul></li><li>Without <code>OAUTH21_BOOTSTRAP=1</code>, the real adapter&#39;s <code>discovery()</code> still returns a valid metadata document (static shape derived from <code>issuer</code>); every other method reports <code>KIWA_OAUTH21_ENV_MISSING</code>.</li></ul><h2 id="release-gate-decision-—-pass" tabindex="-1">Release gate decision — PASS <a class="header-anchor" href="#release-gate-decision-—-pass" aria-label="Permalink to &quot;Release gate decision — PASS&quot;">​</a></h2><p>All 7 axes have mock coverage that runs unconditionally + a real column that either runs live (discovery under v1.22-2 opt-in) or documents the env-skip contract. The v1.21-3 milestone (<code>#844</code>) closed on the mock adapter; v1.22-2 (<code>#888</code>) extends real coverage to the discovery axis + fixes Bug 1 (§4.1.2.1 redirect fidelity).</p><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li><strong>Ceremonial endpoint live coverage</strong> — extend <code>OAuth21ASAdapter</code> with async counterparts (<code>authorizeLive()</code> / <code>tokenLive()</code> / <code>revokeLive()</code> / <code>introspectLive()</code>) so the ceremonial axes get live diffs against Navikt&#39;s mock. Kept as a separate Sub-Issue because the sync interface preserves parity with the kiwa mock&#39;s in-process contract; wiring async live methods requires re-designing the fidelity grid.</li><li><strong>v1.22-3 (<code>dogfood-oidc-federation</code>) Nuxt 3 RP full flow + a11y axe-core gate</strong> — layers the RP-side journey on top of v1.22-1&#39;s real Keycloak driver.</li><li><strong>v1.22-4 (Passkey caBLE)</strong> — CTAP2 hybrid transport real device flow.</li><li><strong>v1.22-5 (Federation JWKS rotation real e2e)</strong> — real Keycloak OP + Nuxt 3 RP + real JWKS endpoint for the rotation ceremony.</li><li><strong>v1.22-6 (docs + release publish)</strong> — tutorial 37-38, migration v1.21→v1.22, plugin.json <code>1.21.0 → 1.22.0</code>, npm + gh-pages publish.</li></ul>',30)])])}const v=t(r,[["render",s]]);export{u as __pageData,v as default};
